"use strict";
// The module-initialization fence the SDKs pi talks to have: a class at
// module scope that extends Promise, which the native compiler refuses, so
// the package runs in a Node island and its values cross as handles.
class SdkPromise extends Promise {}
exports.SdkPromise = SdkPromise;
exports.send = (p, input, betas) => JSON.stringify({ p, input, betas });
exports.assistant = () => ({ role: "assistant", content: null });
